add='''class AddTransactionPage extends StatefulWidget{const AddTransactionPage({super.key,required this.store,required this.customer});final Store store;final Customer customer;@override State<AddTransactionPage> createState()=>_AddTransactionPageState();}
class _AddTransactionPageState extends State<AddTransactionPage>{
 final amount=TextEditingController(),note=TextEditingController(),voiceText=TextEditingController(); final picker=ImagePicker(); final speech=stt.SpeechToText(); String type='debt',receiptPath='',receiptUrl=''; bool listening=false;
 Future<void> voice()async{if(listening){await speech.stop();if(mounted)setState(()=>listening=false);return;}final ok=await speech.initialize(onStatus:(x){if(mounted)setState(()=>listening=x=='listening');},onError:(_){if(mounted)setState(()=>listening=false);});if(!ok){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('تعذر تشغيل الميكروفون')));return;}if(mounted)setState(()=>listening=true);await speech.listen(localeId:'ar-LY',partialResults:true,onResult:(r){voiceText.text=r.recognizedWords;final m=RegExp(r'(\\d+(?:[.,]\\d+)?)').firstMatch(r.recognizedWords);if(m!=null)amount.text=m.group(1)!.replaceAll(',','.');if(r.finalResult&&mounted)setState(()=>listening=false);});}
 Future<void> receipt()async{final src=await showModalBottomSheet<ImageSource>(context:context,builder:(c)=>SafeArea(child:Column(mainAxisSize:MainAxisSize.min,children:[ListTile(leading:const Icon(Icons.camera_alt),title:const Text('تصوير الإيصال'),onTap:()=>Navigator.pop(c,ImageSource.camera)),ListTile(leading:const Icon(Icons.photo_library),title:const Text('اختيار من المعرض'),onTap:()=>Navigator.pop(c,ImageSource.gallery))])));if(src==null)return;final x=await picker.pickImage(source:src,imageQuality:85,maxWidth:1800,maxHeight:2400);if(x==null)return;final dir=await getApplicationDocumentsDirectory();final rd=Directory('${dir.path}/receipts');await rd.create(recursive:true);final f=await File(x.path).copy('${rd.path}/receipt_${DateTime.now().microsecondsSinceEpoch}.jpg');receiptPath=f.path;if(widget.store.firebaseReady){try{final r=FirebaseStorage.instance.ref('users/${widget.store.uid}/receipts/${f.uri.pathSegments.last}');await r.putFile(f);receiptUrl=await r.getDownloadURL();}catch(_){}}if(mounted)setState((){});}
 Future<void> save()async{if(widget.store.locked){if(mounted)Navigator.pop(context);return;}final a=double.tryParse(amount.text.replaceAll(',','.'))??0;if(a<=0){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('أدخل مبلغًا صحيحًا')));return;}if(type=='debt'&&widget.customer.limit>0){final b=widget.store.balance(widget.customer.id);if(b+a>widget.customer.limit){final avail=max(0.0,widget.customer.limit-b);await showDialog(context:context,builder:(_)=>AlertDialog(title:const Text('تجاوز السقف الائتماني'),content:Text('لا يمكن تسجيل الدين. السقف ${money(widget.customer.limit)} والمتاح ${money(avail)}.'),actions:[TextButton(onPressed:()=>Navigator.pop(context),child:const Text('حسنًا'))]));return;}}widget.store.transactions.add(Tx(id:makeId(),customerId:widget.customer.id,type:type,amount:a,date:DateTime.now(),note:note.text.trim(),receiptPath:receiptPath,receiptUrl:receiptUrl));await widget.store.save();if(mounted)Navigator.pop(context);}
 @override Widget build(BuildContext context)=>Directionality(textDirection:TextDirection.rtl,child:Scaffold(appBar:AppBar(title:Text(type=='debt'?'إضافة دَين':'تسجيل تسديد')),body:ListView(padding:const EdgeInsets.all(16),children:[Card(child:ListTile(title:Text(widget.customer.name),subtitle:Text('الرصيد ${money(widget.store.balance(widget.customer.id))}'),trailing:widget.customer.limit>0?Text('السقف ${money(widget.customer.limit)}'):null)),const SizedBox(height:10),SegmentedButton<String>(segments:const[ButtonSegment(value:'debt',label:Text('دَين')),ButtonSegment(value:'payment',label:Text('تسديد'))],selected:{type},onSelectionChanged:(v)=>setState(()=>type=v.first)),TextField(controller:amount,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'المبلغ بالدينار الليبي')),TextField(controller:note,decoration:const InputDecoration(labelText:'ملاحظات')),const SizedBox(height:8),OutlinedButton.icon(onPressed:voice,icon:Icon(listening?Icons.stop:Icons.mic),label:Text(listening?'إيقاف التسجيل':'تسجيل العملية بالصوت')),if(voiceText.text.isNotEmpty)TextField(controller:voiceText,readOnly:true,decoration:const InputDecoration(labelText:'النص المسموع')),const SizedBox(height:8),Card(child:ListTile(leading:const Icon(Icons.receipt_long),title:const Text('صورة الإيصال اختيارية'),subtitle:Text(receiptPath.isEmpty?'التقاط صورة من داخل التطبيق أو اختيارها':'تم إرفاق الإيصال'),trailing:IconButton(onPressed:receipt,icon:const Icon(Icons.add_a_photo)))),if(receiptPath.isNotEmpty)Padding(padding:const EdgeInsets.only(top:8),child:ClipRRect(borderRadius:BorderRadius.circular(12),child:Image.file(File(receiptPath),height:180,fit:BoxFit.contain))),const SizedBox(height:20),FilledButton(onPressed:save,child:const Text('حفظ العملية'))])));}
}'''
